(function(){'use strict';var WebsiteAssistant={config:{apiKey:'',apiEndpoint:'http://localhost:8000/api/v1',theme:'dark',position:'bottom-right',primaryColor:'#6366f1',welcomeMessage:"Hello! I am the AI Digital Twin of Alemu Kibret Mulugeta. Ask me about Alemu's research, projects, skills, or download his resume!"},state:{isOpen:false,sessionId:'sess_'+Math.random().toString(36).substring(2,12),messages:[],isStreaming:false},elements:{},init:function(options){if(options){for(var key in options){if(options.hasOwnProperty(key)){this.config[key]=options[key];}}}this.injectStyles();this.renderWidget();this.bindEvents();this.addWelcomeMessage();},injectStyles:function(){if(document.getElementById('wa-widget-styles'))return;var link=document.createElement('link');link.id='wa-widget-styles';link.rel='stylesheet';link.href=this.config.apiEndpoint.replace('/api/v1','')+'/widget.css';document.head.appendChild(link);},renderWidget:function(){var container=document.createElement('div');container.className='wa-widget-container wa-position-'+this.config.position;container.setAttribute('data-theme',this.config.theme);container.innerHTML='<div class="wa-chat-panel" id="wa-chat-panel"><div class="wa-header"><div class="wa-header-info"><div class="wa-avatar">AK</div><div><h4 class="wa-title">Alemu Kibret AI</h4><p class="wa-subtitle">Digital Twin • Online</p></div></div><div class="wa-header-actions"><button class="wa-icon-btn" id="wa-theme-btn" title="Toggle Theme"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg></button><button class="wa-icon-btn" id="wa-reset-btn" title="Reset Chat"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg></button><button class="wa-icon-btn" id="wa-close-btn" title="Close"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 18L18 6M6 6l12 12"/></svg></button></div></div><div class="wa-body" id="wa-body"></div><div class="wa-footer"><input type="text" class="wa-input" id="wa-input" placeholder="Ask about research, projects, skills..." /><button class="wa-send-btn" id="wa-send-btn"><svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg></button></div></div><button class="wa-toggle-btn" id="wa-toggle-btn"><div class="wa-badge"></div><svg viewBox="0 0 24 24"><path d="M20 2H4c-1.1 0-1.99.9-1.99 2L2 22l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 9h12v2H6V9zm8 5H6v-2h8v2zm4-6H6V6h12v2z"/></svg></button>';document.body.appendChild(container);this.elements={container:container,panel:document.getElementById('wa-chat-panel'),toggleBtn:document.getElementById('wa-toggle-btn'),closeBtn:document.getElementById('wa-close-btn'),themeBtn:document.getElementById('wa-theme-btn'),resetBtn:document.getElementById('wa-reset-btn'),body:document.getElementById('wa-body'),input:document.getElementById('wa-input'),sendBtn:document.getElementById('wa-send-btn')};},bindEvents:function(){var self=this;self.elements.toggleBtn.addEventListener('click',function(){self.toggleWidget();});self.elements.closeBtn.addEventListener('click',function(){self.toggleWidget(false);});self.elements.themeBtn.addEventListener('click',function(){self.toggleTheme();});self.elements.resetBtn.addEventListener('click',function(){self.resetChat();});self.elements.sendBtn.addEventListener('click',function(){self.handleSend();});self.elements.input.addEventListener('keydown',function(e){if(e.key==='Enter'){self.handleSend();}});},toggleWidget:function(open){if(typeof open==='boolean'){this.state.isOpen=open;}else{this.state.isOpen=!this.state.isOpen;}if(this.state.isOpen){this.elements.panel.classList.add('wa-open');this.elements.input.focus();}else{this.elements.panel.classList.remove('wa-open');}},toggleTheme:function(){this.config.theme=this.config.theme==='dark'?'light':'dark';this.elements.container.setAttribute('data-theme',this.config.theme);},addWelcomeMessage:function(){this.appendMessage('assistant',this.config.welcomeMessage);},resetChat:function(){this.elements.body.innerHTML='';this.state.messages=[];this.state.sessionId='sess_'+Math.random().toString(36).substring(2,12);this.addWelcomeMessage();},handleSend:function(){var text=this.elements.input.value?this.elements.input.value.trim():'';if(!text||this.state.isStreaming)return;this.elements.input.value='';this.appendMessage('user',text);this.streamResponse(text);},appendMessage:function(role,content){var msgDiv=document.createElement('div');msgDiv.className='wa-message wa-msg-'+role;var bubble=document.createElement('div');bubble.className='wa-bubble';bubble.innerHTML=this.parseMarkdown(content);msgDiv.appendChild(bubble);this.elements.body.appendChild(msgDiv);this.scrollToBottom();this.state.messages.push({role:role,content:content});return bubble;},streamResponse:function(query){var self=this;self.state.isStreaming=true;var typingDiv=document.createElement('div');typingDiv.className='wa-message wa-msg-assistant';typingDiv.innerHTML='<div class="wa-bubble wa-typing"><div class="wa-dot"></div><div class="wa-dot"></div><div class="wa-dot"></div></div>';self.elements.body.appendChild(typingDiv);self.scrollToBottom();var streamUrl=self.config.apiEndpoint+'/chat/stream?message='+encodeURIComponent(query)+'&session_id='+encodeURIComponent(self.state.sessionId);var responseBubble=null;var accumulatedText='';if(window.EventSource){var es=new EventSource(streamUrl);es.onmessage=function(event){try{var data=JSON.parse(event.data);if(data.type==='content'&&data.delta){if(!responseBubble){self.elements.body.removeChild(typingDiv);responseBubble=self.appendMessage('assistant','');}accumulatedText+=data.delta;responseBubble.innerHTML=self.parseMarkdown(accumulatedText);if(data.action){self.renderActionCard(responseBubble,data.action);}self.scrollToBottom();}else if(data.type==='done'){es.close();self.state.isStreaming=false;}}catch(e){console.error('SSE Error',e);}};es.onerror=function(){es.close();if(!responseBubble){self.elements.body.removeChild(typingDiv);self.appendMessage('assistant','Sorry, I encountered an issue connecting to the digital twin service.');}self.state.isStreaming=false;};}else{fetch(self.config.apiEndpoint+'/chat/message',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:query,session_id:self.state.sessionId})}).then(function(res){return res.json();}).then(function(data){self.elements.body.removeChild(typingDiv);var b=self.appendMessage('assistant',data.response||'No response.');if(data.action){self.renderActionCard(b,data.action);}self.state.isStreaming=false;}).catch(function(){self.elements.body.removeChild(typingDiv);self.appendMessage('assistant','Sorry, an error occurred.');self.state.isStreaming=false;});}},renderActionCard:function(containerBubble,action){if(!action||!action.name)return;var card=document.createElement('div');card.className='wa-action-card';if(action.name==='download_resume'&&action.data&&action.data.download_url){card.innerHTML='<div class="wa-action-title">📄 Resume Ready for Download</div><a class="wa-btn" href="'+action.data.download_url+'" target="_blank" download>Download Resume (PDF)</a>';}else if(action.name==='list_projects'&&action.data&&action.data.projects){var items=action.data.projects.map(function(p){return '<div style="margin-bottom:6px;"><strong>'+p.title+'</strong><br/><small>'+p.tech_stack.join(', ')+'</small></div>';}).join('');card.innerHTML='<div class="wa-action-title">🚀 Featured Projects</div>'+items;}containerBubble.appendChild(card);},parseMarkdown:function(text){if(!text)return'';var escaped=text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');escaped=escaped.replace(/```([\s\S]*?)```/g,function(match,p1){return'<div class="wa-code-block"><div class="wa-code-header"><span>Code</span><button class="wa-copy-btn" onclick="navigator.clipboard.writeText(this.parentNode.nextElementSibling.innerText)">Copy</button></div><pre class="wa-code-content"><code>'+p1.trim()+'</code></pre></div>';});escaped=escaped.replace(/`([^`]+)`/g,'<code>$1</code>');escaped=escaped.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');escaped=escaped.replace(/\*([^*]+)\*/g,'<em>$1</em>');return escaped.replace(/\n/g,'<br/>');},scrollToBottom:function(){this.elements.body.scrollTop=this.elements.body.scrollHeight;}};window.WebsiteAssistant=WebsiteAssistant;})();
